command:
// ==========================================
// LUNAS WIRKUNG: RUF DER MUTTER (NURTI)
// Framework V01.02 + Block 19
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    if (!globalThis.DSK?.Effekt || !globalThis.DSK?.QS || !globalThis.DSK?.Token || !globalThis.DSK?.Empfaenger || !globalThis.DSK?.GMAnfrage || !globalThis.DSK?.Geometrie || !globalThis.DSK?.GabenUI) {
        const framework = await fromUuid(frameworkUuid);
        if (!framework) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await framework.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (!DSK_FW?.Effekt || !DSK_FW?.QS || !DSK_FW?.Token || !DSK_FW?.Empfaenger || !DSK_FW?.GMAnfrage || !DSK_FW?.Geometrie || !DSK_FW?.GabenUI) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");
    }

    const gabenName = "Ruf der Mutter", ahne = "Nurti", vollerName = `${gabenName} (${ahne})`, flagKey = "pendingRufDerMutterNurti", symbolPfad = DSK_FW.Symbol(ahne);
    const pause = ms => new Promise(resolve => setTimeout(resolve, Math.max(0, Number(ms) || 0)));

    const wirkungsBeschreibung = `
        Das Nurtikind sendet einen weithin hörbaren Ruf an seine Liebsten aus. Ausgewählte Freunde oder Verwandte können den Ruf hören und ungefähr bestimmen, wie weit entfernt und in welcher Richtung sich das Nurtikind befindet.
        <br><br>Solange der Ruf wirkt, können sich die verbundenen Personen erneut auf den Ruf konzentrieren, um Entfernung und Richtung neu zu bestimmen.
        <br><br><b>Zielkategorie:</b> Freunde und Verwandte des Nurtikindes
        <br><b>Reichweite:</b> QS × 100 Schritt
        <br><b>Maximale Ziele:</b> QS Personen
        <br><b>Wirkungsdauer:</b> QS × 5 Minuten
    `;

    const alterEndHookKey = "_hook_end_rufDerMutterNurti";
    if (globalThis[alterEndHookKey]) {
        Hooks.off("preDeleteActiveEffect", globalThis[alterEndHookKey]);
        delete globalThis[alterEndHookKey];
    }

    const normalisiereName = name => {
        if (DSK_FW.Schaden?.NormalisiereName && DSK_FW.Schaden?.EntferneNummerierung) {
            return DSK_FW.Schaden.NormalisiereName(DSK_FW.Schaden.EntferneNummerierung(name));
        }
        return String(name || "").toLowerCase().replace(/\u00a0/g, " ").replace(/[„“"']/g, "").replace(/\s*\(\d+\)\s*$/i, "").replace(/\s+/g, " ").trim();
    };

    const leseFreundesliste = actor => {
        const item = actor?.items?.find(e => {
            const name = normalisiereName(e.name);
            return name.includes("freunde und verwandte") || name.includes("freunde & verwandte") || name === "freunde";
        });
        if (!item) return [];
        const rawText = item.system?.description?.value || item.system?.description || item.system?.value || "";
        const element = document.createElement("div");
        element.innerHTML = String(rawText).replace(/<\/p>|<\/li>|<br\s*\/?>/gi, "\n");
        const text = String(element.textContent || element.innerText || "").replace(/\u00a0/g, " ").replace(/\r/g, "\n");
        return [...new Set(text.split(/[\n,;]+/).map(n => String(n).replace(/^[•*+\-\s]+|[•*+\-\s]+$/g, "").replace(/\s+/g, " ").trim()).filter(Boolean))];
    };

    const passtZurFreundesliste = (token, freundesliste) => {
        if (!token?.actor) return false;
        const tokenName = normalisiereName(token.name), actorName = normalisiereName(token.actor.name);
        return freundesliste.some(e => {
            const listenName = normalisiereName(e);
            return listenName && (tokenName === listenName || actorName === listenName || tokenName.includes(listenName) || actorName.includes(listenName) || listenName.includes(tokenName) || listenName.includes(actorName));
        });
    };

    const findeCasterEffekt = actor => actor?.effects?.find(e => !e.disabled && e.getFlag("dsk", "isRufCaster") === true) || null;
    const findeZielEffekt = (actor, casterUuid) => actor?.effects?.find(e => !e.disabled && e.getFlag("dsk", "isRufTarget") === true && e.getFlag("dsk", "casterUuid") === casterUuid) || null;
    const findeGehoertenRuf = actor => actor?.effects?.find(e => !e.disabled && e.getFlag("dsk", "isRufTarget") === true && Boolean(e.getFlag("dsk", "casterUuid"))) || null;
    const findeTokenUeberUuid = uuid => canvas.tokens.placeables.find(t => t.document?.uuid === uuid || t.uuid === uuid) || null;

    const ladeCasterVerbindung = async (casterUuid, casterTokenUuid) => {
        const gesToken = findeTokenUeberUuid(casterTokenUuid);
        if (gesToken?.actor) return { actor: gesToken.actor, token: gesToken };
        let actor = null;
        if (casterUuid) {
            try {
                const doc = await fromUuid(casterUuid);
                actor = doc?.documentName === "Token" ? doc.actor : doc;
            } catch { actor = null; }
        }
        return { actor, token: actor ? DSK_FW.Token.Finde(actor, null, casterTokenUuid) : null };
    };

    const findeMoeglicheZiele = (casterToken, freundesliste, reichweite) =>
        canvas.tokens.placeables
            .filter(t => t?.actor && t.id !== casterToken.id && DSK_FW.Effekt.CheckTarget(t.actor, "erwachte") && passtZurFreundesliste(t, freundesliste) && DSK_FW.Geometrie.Distanz(casterToken, t) <= reichweite)
            .map(t => ({ token: t, position: DSK_FW.Geometrie.PositionInfo(t, casterToken, { nachkommastellen: 1 }) }))
            .sort((a, b) => String(a.token.name).localeCompare(String(b.token.name), "de"));

    const waehleZiele = async ({ casterName, qs, reichweite, dauer, moeglicheZiele }) => {
        const zielHtml = moeglicheZiele.map(({ token, position }) => `
            <label style="display:flex;align-items:flex-start;gap:7px;margin-bottom:6px;padding:6px 8px;cursor:pointer;background:rgba(255,255,255,0.35);border-radius:3px;">
                <input type="checkbox" name="rufZiel" value="${token.id}">
                <span><b>${token.name}</b><br><span style="color:#555;font-size:0.82em;">${position.distanz} Schritt; ${position.richtung} (${position.richtungKurz})</span></span>
            </label>
        `).join("");

        return foundry.applications.api.DialogV2.wait({
            window: { title: vollerName },
            position: { width: 500 },
            content: `
                <form>
                    ${DSK_FW.UI.Header(vollerName, symbolPfad)}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p><b>${casterName}</b> sendet den Ruf der Mutter aus.</p>
                        <ul class="dsklist">
                            <li><b>QS:</b> ${qs}</li>
                            <li><b>Maximale Ziele:</b> ${qs}</li>
                            <li><b>Reichweite:</b> ${reichweite} Schritt</li>
                            <li><b>Wirkungsdauer:</b> ${dauer} Minuten</li>
                        </ul>
                        <hr>
                        <p><b>Welche Freunde oder Verwandten sollen den Ruf hören?</b></p>
                        <div style="max-height:280px;overflow-y:auto;padding:8px;background:rgba(0,0,0,0.05);border-radius:4px;">${zielHtml}</div>
                        <p style="margin-bottom:0;color:#555;font-size:0.85em;"><i>Wähle höchstens <b>${qs}</b> Personen aus.</i></p>
                    </div>
                </form>
            `,
            buttons: [
                { action: "ok", label: "Ruf senden", icon: "fas fa-bullhorn", default: true, callback: e => Array.from(e.target.closest("form").querySelectorAll('input[name="rufZiel"]:checked')).map(i => i.value) },
                { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => null }
            ],
            rejectClose: false
        });
    };

    const sendeOrtungskarte = async ({ zielActor, zielToken, casterToken, casterName, casterUuid, casterTokenUuid, reichweite, aktualisiert = false }) => {
        const empfaenger = [...new Set([...DSK_FW.Empfaenger.Besitzer(zielActor), ...DSK_FW.Empfaenger.GM()])];
        if (empfaenger.length === 0) return;

        const position = DSK_FW.Geometrie.PositionInfo(zielToken, casterToken, { nachkommastellen: 0 });

        // Sauberer, roter Framework-Button ohne GM-Berechtigungsprüfung
        const erneutLink = `<button type="button" class="dsk-btn-ruf-neu" style="${DSK_FW.GabenUI.ButtonStyle()}"><i class="fas fa-location-crosshairs"></i> Neu auf den Ruf konzentrieren</button>`;

        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: empfaenger,
            flags: { dsk: { rufDerMutterOrtungsKarte: true, casterUuid, casterTokenUuid, zielTokenUuid: zielToken.document?.uuid || zielToken.uuid || null } },
            content: `
                ${DSK_FW.UI.Header(vollerName, symbolPfad)}
                <div class="dskbox2" style="margin-top:10px;text-align:center;">
                    <p style="margin-top:0;color:#18940F;font-weight:bold;">${aktualisiert ? "Ortung aktualisiert" : "Verbindung hergestellt"}</p>
                    <p><b>${casterName}</b> sendet den Ruf der Mutter aus.</p>
                    <p>Der Ruf wurde von <b>${zielToken.name}</b> vernommen.</p>
                    <hr>
                    <p style="line-height:1.45;"><b>${casterName}</b> befindet sich ungefähr <b>${position.distanz} Schritt</b> entfernt im <b>${position.richtung}</b> (${position.richtungKurz}).</p>
                    <p style="color:#555;font-size:0.86em;">Maximale Rufreichweite: ${reichweite} Schritt</p>
                    <hr><div style="font-size:1.05em;">${erneutLink}</div>
                </div>
            `
        });
    };

    // Globaler Klick-Listener für den eigenen roten Button (ohne Fehlermeldung für Spieler)
    if (globalThis._dskRufNeuListener) {
        document.removeEventListener("click", globalThis._dskRufNeuListener);
    }
    globalThis._dskRufNeuListener = async event => {
        const btn = event.target.closest(".dsk-btn-ruf-neu");
        if (!btn) return;

        event.preventDefault();
        event.stopPropagation();

        let actor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
        if (!actor) {
            for (const t of canvas.tokens.placeables) {
                if (t.actor && t.actor.isOwner) { actor = t.actor; break; }
            }
        }
        if (!actor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle deinen Token aus!");

        const gehoerterRuf = findeGehoertenRuf(actor) || findeCasterEffekt(actor);
        if (!gehoerterRuf) return ui.notifications.warn("Luna sagt 🌙: Kein aktiver Ruf gefunden.");

        const casterUuid = gehoerterRuf.getFlag("dsk", "casterUuid") || actor.uuid;
        const casterTokenUuid = gehoerterRuf.getFlag("dsk", "casterTokenUuid") || null;

        const verbindung = await ladeCasterVerbindung(casterUuid, casterTokenUuid);
        if (!verbindung.actor || !verbindung.token) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende wurde nicht gefunden.");

        const zielToken = DSK_FW.Token.Finde(actor);
        if (!zielToken) return ui.notifications.warn("Luna sagt 🌙: Dein Token wurde nicht gefunden.");

        const reichweite = Number(gehoerterRuf.getFlag("dsk", "radiusMeter") || 500);
        const casterName = gehoerterRuf.getFlag("dsk", "casterName") || DSK_FW.ResolveTokenName(verbindung.actor);

        ui.notifications.info("Luna sagt 🌙: Ortung aktualisiert.");

        await sendeOrtungskarte({
            zielActor: actor,
            zielToken: zielToken,
            casterToken: verbindung.token,
            casterName,
            casterUuid,
            casterTokenUuid,
            reichweite,
            aktualisiert: true
        });
    };
    document.addEventListener("click", globalThis._dskRufNeuListener);

    const sendeAllgemeineGabenkarte = async ({ casterName, ziele, qs, reichweite, dauer, messageId = null }) => {
        const erklaerung = DSK_FW.GabenUI.Details({ titel: "Gabenwirkung Information", inhalt: wirkungsBeschreibung, zentriert: true });

        const kartenInhalt = `
            ${DSK_FW.UI.Header(vollerName, symbolPfad)}
            <div class="dskbox2" style="margin-top:10px;">
                ${erklaerung}
                <hr style="margin:10px 0;border:0;border-top:1px solid #c9bca6;">
                <p style="text-align:center;color:#18940F;font-weight:bold;margin-top:0;">Der Ruf der Mutter erklingt.</p>
                <p style="text-align:center;"><b>${casterName}</b> lässt seinen Ruf zu den Liebsten hinausdringen.</p>
                <p style="text-align:center;margin-bottom:10px;">Für die nächsten <b>${dauer} Minuten</b> können die ausgewählten Liebsten den Ruf des Nurtikindes hören.</p>
                <hr><p style="margin-bottom:5px;"><b>Der Ruf erreicht:</b></p>
                ${DSK_FW.UI.List(ziele.map(t => `<b>${t.name}</b>`))}
                <hr>
                <ul class="dsklist">
                    <li><b>Qualitätsstufe:</b> ${qs}</li>
                    <li><b>Reichweite:</b> ${reichweite} Schritt</li>
                    <li><b>Wirkungsdauer:</b> ${dauer} Minuten</li>
                </ul>
                <hr>
                <p style="text-align:center;margin-bottom:0;color:#555;font-size:0.9em;">Solange der Ruf erklingt, können sich die Verbundenen erneut auf den Ruf konzentrieren und seine Richtung bestimmen.</p>
            </div>
        `;

        if (messageId) {
            const msg = game.messages.get(messageId);
            if (msg) {
                await msg.update({ content: kartenInhalt, "flags.dsk.angewendet": true });
                return msg;
            }
        }

        return ChatMessage.create({
            speaker: { alias: "System" },
            flags: { dsk: { gabenAnfrage: true, gabenName, angewendet: true } },
            content: kartenInhalt
        });
    };

    const verarbeiteErstwirken = async (casterToken, daten) => {
        const casterActor = casterToken?.actor;
        if (!casterActor) return false;
        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1)), reichweite = Math.max(1, Number(daten.reichweite) || qs * 100), dauer = qs * 5;
        const casterUuid = casterActor.uuid, casterTokenUuid = casterToken.document?.uuid || casterToken.uuid || null, casterName = DSK_FW.ResolveTokenName(casterActor);
        const freundesliste = leseFreundesliste(casterActor);

        const ziele = (Array.isArray(daten.zielTokenIds) ? daten.zielTokenIds : [])
            .map(id => canvas.tokens.get(id))
            .filter(t => t?.actor && DSK_FW.Effekt.CheckTarget(t.actor, "erwachte") && passtZurFreundesliste(t, freundesliste) && DSK_FW.Geometrie.Distanz(casterToken, t) <= reichweite)
            .slice(0, qs);

        if (ziele.length === 0) return ui.notifications.warn("Luna sagt 🌙: Die ausgewählten Personen sind nicht mehr erreichbar."), false;

        const zielTokenUuids = ziele.map(t => t.document?.uuid || t.uuid || null).filter(Boolean);
        let casterEffekt = findeCasterEffekt(casterActor);

        if (!casterEffekt) {
            await DSK_FW.Effekt.Anwenden({
                name: vollerName, ahne,
                beschreibung: `<b>${casterName}</b> sendet den Ruf der Mutter aus.<br><br><b>Reichweite:</b> ${reichweite} Schritt<br><b>Wirkungsdauer:</b> ${dauer} Minuten`,
                gabeZiel: "erwachte", qs, ziel: casterActor,
                flags: { dsk: { isRufCaster: true, rolle: "wirkender", casterUuid, casterTokenUuid, casterName, qsWert: qs, radiusMeter: reichweite, dauerMinuten: dauer, zielTokenUuids, sceneId: canvas.scene?.id || null, ahne, basisName: gabenName } }
            });
            await pause(1000);
            casterEffekt = findeCasterEffekt(casterActor);
        } else {
            const bisherige = casterEffekt.getFlag("dsk", "zielTokenUuids") || [];
            await casterEffekt.update({ "flags.dsk.zielTokenUuids": [...new Set([...bisherige, ...zielTokenUuids])] });
        }

        if (!casterEffekt) return ui.notifications.warn("Luna sagt 🌙: Der Haupteffekt konnte nicht angelegt werden."), false;

        for (const t of ziele) {
            const zielActor = t.actor;
            if (!zielActor) continue;
            let zielEffekt = findeZielEffekt(zielActor, casterUuid);

            if (!zielEffekt) {
                await DSK_FW.Effekt.Anwenden({
                    name: `${vollerName} - gehört wird ${casterName}`, ahne,
                    beschreibung: `<b>${casterName}</b> Effekt aktiv.`,
                    gabeZiel: "erwachte", qs, ziel: zielActor,
                    flags: { dsk: { isRufTarget: true, rolle: "ziel", casterUuid, casterTokenUuid, casterName, zielTokenUuid: t.document?.uuid || t.uuid || null, qsWert: qs, radiusMeter: reichweite, sceneId: canvas.scene?.id || null, ahne, basisName: gabenName } }
                });
                await pause(1000);
                zielEffekt = findeZielEffekt(zielActor, casterUuid);
            }
            if (!zielEffekt) continue;
            await sendeOrtungskarte({ zielActor, zielToken: t, casterToken, casterName, casterUuid, casterTokenUuid, reichweite, aktualisiert: false });
        }

        await sendeAllgemeineGabenkarte({ casterName, ziele, qs, reichweite, dauer, messageId: daten.messageId });
        return true;
    };

    const beendeRuf = async casterEffekt => {
        if (!casterEffekt) return;
        const aktiverGM = game.users.find(u => u.isGM && u.active);
        if ((aktiverGM ? aktiverGM.id !== game.user.id : !game.user.isGM)) return;

        const casterActor = casterEffekt.parent, casterUuid = casterEffekt.getFlag("dsk", "casterUuid") || casterActor?.uuid;
        if (!casterUuid) return;

        const betroffeneNamen = [];
        if (casterActor) betroffeneNamen.push(DSK_FW.ResolveTokenName(casterActor));

        for (const t of canvas.tokens.placeables) {
            if (!t.actor) continue;
            const effekte = t.actor.effects.filter(e => e.getFlag("dsk", "isRufTarget") === true && e.getFlag("dsk", "casterUuid") === casterUuid);
            if (effekte.length === 0) continue;
            betroffeneNamen.push(t.name || t.actor.name);
            await t.actor.deleteEmbeddedDocuments("ActiveEffect", effekte.map(e => e.id));
            await pause(1000);
        }

        const eindeutigeNamen = [...new Set(betroffeneNamen.filter(Boolean))];
        await ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                <div style="font-family:'Signika',sans-serif;">
                    <div class="dskbox1">
                        <p style="display:flex;gap:8px;align-items:center;margin:0;">
                            <img src="${symbolPfad}" style="width:28px;border:none;background:transparent;">
                            <b style="font-size:1.1em;">Wirkungsende</b>
                        </p>
                        <hr style="margin:4px 0;border:0;border-top:1px solid #c9bca6;">
                        <p style="font-weight:bold;margin:0;padding-top:2px;">${vollerName}</p>
                    </div>
                    <div class="dskbox2" style="margin-top:10px;">
                        <p>Der Ruf der Mutter verhallt. Die mütterliche Verbindung ist getrennt.</p>
                        <p style="font-size:0.9em;color:#555;">Einheiten/Erschwernisse verflogen.</p>
                        <hr style="margin:6px 0;border:0;border-top:1px solid #c9bca6;">
                        <p style="margin-bottom:5px;"><b>Effekt beendet auf:</b></p>
                        ${DSK_FW.UI.List(eindeutigeNamen)}
                    </div>
                </div>
            `
        });
    };

    if (globalThis._dskRufDerMutterCleanupHook) Hooks.off("deleteActiveEffect", globalThis._dskRufDerMutterCleanupHook);
    globalThis._dskRufDerMutterCleanupHook = Hooks.on("deleteActiveEffect", async effect => {
        if (effect.getFlag("dsk", "isRufCaster") !== true) return;
        await beendeRuf(effect);
    });

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);
        if (anfragen.length > 0) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten || (daten.sceneId && daten.sceneId !== canvas.scene?.id)) continue;
                const casterToken = DSK_FW.Token.Finde(anfrageActor, daten.casterTokenId, daten.casterTokenUuid);
                if (!casterToken) continue;
                if (await verarbeiteErstwirken(casterToken, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }
            return;
        }
    }

    let ausfuehrenderActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
    if (!ausfuehrenderActor) {
        ausfuehrenderActor = canvas.tokens.placeables.map(t => t.actor).find(a => a?.getFlag("world", "letzteGabenQS") !== undefined) || game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined) || null;
    }
    if (!ausfuehrenderActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle den passenden Token aus!");

    const casterActor = ausfuehrenderActor;
    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Das Token des Nurtikindes wurde nicht gefunden!");

    const freundesliste = leseFreundesliste(casterActor);
    if (freundesliste.length === 0) return ui.notifications.warn("Luna sagt 🌙: Keine Namen in „Freunde und Verwandte“ gefunden!");

    const qs = DSK_FW.QS.Ermitteln({ actor: casterActor, gabenName, suchbegriffe: ["Ruf der Mutter Probe", "Ruf der Mutter"], testDataObj: typeof testData !== "undefined" ? testData : null, fallback: 0, protokollieren: true });
    if (qs <= 0) return ui.notifications.warn("Luna sagt 🌙: Die Qualitätsstufe konnte nicht ermittelt werden!");

    const reichweite = qs * 100, dauer = qs * 5, casterName = DSK_FW.ResolveTokenName(casterActor);
    const moeglicheZiele = findeMoeglicheZiele(casterToken, freundesliste, reichweite);
    if (moeglicheZiele.length === 0) return ui.notifications.warn("Luna sagt 🌙: Keine eingetragenen Freunde oder Verwandten innerhalb der Reichweite.");

    const auswahl = await waehleZiele({ casterName, qs, reichweite, dauer, moeglicheZiele });
    if (!auswahl || auswahl.length === 0) return ui.notifications.warn("Luna sagt 🌙: Es wurde keine Person ausgewählt.");
    if (auswahl.length > qs) return ui.notifications.warn(`Luna sagt 🌙: Es dürfen maximal ${qs} Personen ausgewählt werden.`);

    const zielTokenIds = auswahl.map(id => canvas.tokens.get(id)).filter(t => t?.actor && DSK_FW.Effekt.CheckTarget(t.actor, "erwachte") && passtZurFreundesliste(t, freundesliste) && DSK_FW.Geometrie.Distanz(casterToken, t) <= reichweite).slice(0, qs).map(t => t.id);
    if (zielTokenIds.length === 0) return ui.notifications.warn("Luna sagt 🌙: Die ausgewählten Personen sind nicht mehr erreichbar.");

    const gmLink = DSK_FW.GabenUI.GMMakroButton(macroUuid, "Effekt anwenden", "Das Makro muss durch die Spielleitung ausgeführt werden.");
    const erklaerung = DSK_FW.GabenUI.Details({ titel: "Gabenwirkung Information", inhalt: wirkungsBeschreibung, zentriert: true });

    const nachricht = await ChatMessage.create({
        speaker: { alias: "System" },
        flags: { dsk: { gabenAnfrage: true, gabenName, angewendet: false, anfragenderUserId: game.user.id } },
        content: `
            ${DSK_FW.UI.Header(vollerName, symbolPfad)}
            <div class="dskbox2" style="margin-top:10px;">
                ${erklaerung}
                <hr style="margin:10px 0;border:0;border-top:1px solid #c9bca6;">
                <p style="text-align:center;color:#18940F;font-weight:bold;margin-top:0;">Der Ruf der Mutter erklingt.</p>
                <p style="text-align:center;"><b>${casterName}</b> lässt seinen Ruf zu den Liebsten hinausdringen.</p>
                <p style="text-align:center;margin-bottom:10px;">Für die nächsten <b>${dauer} Minuten</b> können die ausgewählten Liebsten den Ruf des Nurtikindes hören.</p>
                <hr><p style="margin-bottom:5px;"><b>Der Ruf erreicht:</b></p>
                ${DSK_FW.UI.List(auswahl.map(id => `<b>${canvas.tokens.get(id)?.name || "Unbekannt"}</b>`))}
                <hr>
                <ul class="dsklist">
                    <li><b>Qualitätsstufe:</b> ${qs}</li>
                    <li><b>Reichweite:</b> ${reichweite} Schritt</li>
                    <li><b>Wirkungsdauer:</b> ${dauer} Minuten</li>
                </ul>
                <hr>
                <p style="text-align:center;margin-bottom:0;color:#555;font-size:0.9em;">Solange der Ruf erklingt, können sich die Verbundenen erneut auf den Ruf konzentrieren und seine Richtung bestimmen.</p>

                <section class="secret">
                    <hr>
                    <div style="text-align:center;">
                        <p style="margin:0 0 6px;color:#76301b;font-weight:bold;">Gabenwirkung Information (Nur SL)</p>
                        <p style="margin:0 0 6px;font-size:.82em;color:#555;">Klicke, um den Effekt auf alle Ziele anzuwenden.</p>
                        <div style="display:flex;justify-content:center;margin-top:6px;">${gmLink}</div>
                    </div>
                </section>
            </div>
        `
    });

    const daten = { 
        modus: "erstwirken", 
        qs, 
        reichweite, 
        casterTokenId: casterToken.id, 
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null, 
        zielTokenIds, 
        sceneId: canvas.scene?.id || null, 
        requestedByUserId: game.user.id,
        messageId: nachricht.id 
    };

    if (game.user.isGM) {
        await verarbeiteErstwirken(casterToken, daten);
    } else {
        await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, daten);
    }

    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
    }

}).call(this);
